import math


def select_links(points, candidates, degree_limit):
    if isinstance(degree_limit, bool) or not isinstance(degree_limit, int):
        raise TypeError("degree_limit must be an integer")
    if degree_limit <= 0:
        raise ValueError("degree_limit must be positive")
    if not isinstance(points, (list, tuple)) or not isinstance(candidates, (list, tuple)):
        raise TypeError("points and candidates must be sequences")

    checked_points = []
    for point in points:
        if not isinstance(point, (list, tuple)) or len(point) != 2:
            raise ValueError("invalid point")
        if any(isinstance(v, bool) or not isinstance(v, (int, float)) for v in point):
            raise TypeError("coordinates must be numeric")
        if not all(math.isfinite(v) for v in point):
            raise ValueError("coordinates must be finite")
        pair = (point[0], point[1])
        if pair in checked_points:
            raise ValueError("points must be distinct")
        checked_points.append(pair)

    unique = set()
    for edge in candidates:
        if not isinstance(edge, (list, tuple)) or len(edge) != 2:
            raise ValueError("invalid candidate")
        u, v = edge
        if isinstance(u, bool) or isinstance(v, bool) or not isinstance(u, int) or not isinstance(v, int):
            raise TypeError("endpoints must be integers")
        if not (0 <= u < len(points) and 0 <= v < len(points)) or u == v:
            raise ValueError("invalid endpoint")
        unique.add((min(u, v), max(u, v)))

    weighted = []
    for u, v in unique:
        distance = math.hypot(checked_points[u][0] - checked_points[v][0], checked_points[u][1] - checked_points[v][1])
        weighted.append((distance, u, v))
    weighted.sort(reverse=True)

    parent = list(range(len(points)))
    degrees = [0] * len(points)

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    accepted = []
    cost = 0.0
    for distance, u, v in weighted:
        ru, rv = find(u), find(v)
        if ru != rv and degrees[u] < degree_limit and degrees[v] < degree_limit:
            parent[ru] = rv
            degrees[u] += 1
            degrees[v] += 1
            accepted.append((u, v))
            cost += distance
            if len(accepted) == max(0, len(points) - 1):
                break
    if len(accepted) != max(0, len(points) - 1):
        raise ValueError("candidates cannot produce the requested tree")
    return {"edges": accepted, "cost": cost, "degrees": degrees}

